function wallTargetLegal25(wall,slot,type,moving){const n=wall==='x'?N:M;if(!Number.isInteger(slot)||slot<0||slot>=n)return false;if(entrancePoints().some(e=>(wall==='x'&&e.side==='top'||wall==='y'&&e.side==='left')&&Math.abs(e.at-slot)<=.6))return false;const width=wallArtSize(type)[0];return !S.design.wallItems.some(i=>i.wall===wall&&moving!=='art:'+i.wall+':'+i.slot&&Math.abs(i.slot-slot)*34<(width+wallArtSize(i.type)[0])/2+3);}
function designTargetAt(e,kind=designEditor?.kind){if(kind!=='art')return before25DesignTargetAt(e,kind);const q=worldAt(e),origin=P(-.5,-.5);for(const wall of ['x','y']){const u=(q.x-origin.x)/(wall==='x'?34:-34),height=origin.y+u*17-q.y,n=wall==='x'?N:M;if(u>=0&&u<n&&height>=3&&height<=84)return wall+':'+Math.max(0,Math.min(n-1,Math.round(u-.5)));}return null;}
function designQuote(){const q=before25DesignQuote();if(designEditor?.kind!=='art'||!q.valid)return q;const [wall,slot]=designEditor.keys[0].split(':');if(!wallTargetLegal25(wall,+slot,designEditor.id,designEditor.moving))return{valid:false,cost:0,count:0,reason:'문·다른 장식과 간격 확보'};return q;}
function hitWall25(e){const q=worldAt(e);for(const i of [...S.design.wallItems].reverse()){const a=i.wall==='x'?P(i.slot,-.5):P(-.5,i.slot),dx=q.x-a.x,dy=q.y-a.y-17-(i.wall==='x'?.5:-.5)*dx,[w,h]=wallArtSize(i.type);if(Math.abs(dx)<=w/2+7&&Math.abs(dy+63)<=h/2+7)return i;}return null;}
function isViewDecor25(f){return [2,3,8,9,10,17,18,19].includes(f.t);}
function updateDecorView25(p,dt){const d=p.decorView25;if(!d)return false;if(S.phase==='closing'||p.state!=='browse'||!S.furniture.some(f=>f.id===d.id)){p.path=path(p,d.resumePath.at(-1)??p.target??p)??[];delete p.decorView25;return false;}if(p.path.length){Motion.advance(p,dt);return true;}Motion.settle(p,dt);d.wait=Math.max(0,d.wait-dt);p.bubble='잠깐 구경해볼까';if(d.wait>0)return true;if(d.gain){const r=customerRecord(p);if(r){if(r.affinityDay!==S.day){r.affinityDay=S.day;r.affinityGain=0;}const gain=Math.min(.1,Math.max(0,Config.affinity.dailyCap-r.affinityGain));r.satisfaction=Math.min(100,Math.round((r.satisfaction+gain)*10)/10);r.affinityGain=Math.round((r.affinityGain+gain)*10)/10;r.regular=r.regular||r.satisfaction>=Config.affinity.regular;}}p.path=path(p,d.resumePath.at(-1)??p.target??p)??[];p.timer=d.resumeTimer;delete p.decorView25;return true;}
