function updateStaffAnimation(dt){const can=dt&&!gameplayBlocked()&&!document.hidden&&!titleActive&&!assetBusy&&!paused&&editing===null&&['open','closing'].includes(S.phase)&&S.staffHired;if(!can)return;const workers=syncStaffFigures();for(let idx=0;idx<workers.length;idx++){const p=workers[idx];if(p.idleWalk25&&staffTripQueue.some(j=>j.worker===idx)){p.idleWalk25=false;p.path=[];p.routeCooldown=0;p.state='idle';p.idleStop25=0;}if(p.idleWalk25){if(S.phase==='closing'){p.path=[];p.idleWalk25=false;}else if(p.path.length){Motion.advance(p,dt);p.state='둘러보는 중';continue;}else{p.idleWalk25=false;p.idleWait25=5+(idx+S.day)%5;p.idleStop25=p.idleWait25;}}if(p.idleStop25>0&&!staffTripQueue.some(j=>j.worker===idx)){p.idleStop25=Math.max(0,p.idleStop25-dt);p.routeCooldown=Math.max(p.routeCooldown??0,dt+1);p.state='대기';Motion.settle(p,dt);}}
 before25UpdateStaffAnimation(dt);
 for(let idx=0;idx<workers.length;idx++){const p=workers[idx];if(p.targetId!=null||p.state==='sorting'||p.path.length||staffTripQueue.some(j=>j.worker===idx)||S.phase!=='open')continue;p.idleWait25=(p.idleWait25??(4+idx*3))-dt;if(p.idleWait25>0)continue;p.idleCycle25=(p.idleCycle25??0)+1;const avoid=[...entrancePoints(),...S.furniture.filter(f=>[1,4,7,13,14].includes(f.t)).map(Furniture.front)];let target=null;for(let n=0;n<16;n++){const a=(p.idleCycle25*2.3+n*.9+idx),candidate={x:Math.round(p.home.x+Math.cos(a)*(1+n%3)),y:Math.round(p.home.y+Math.sin(a)*(1+n%3))};if(candidate.x<0||candidate.y<0||candidate.x>=N||candidate.y>=M||inVIP(candidate)||Math.hypot(candidate.x-p.x,candidate.y-p.y)<.5||S.furniture.some(f=>Furniture.blocks(f,candidate.x,candidate.y))||avoid.some(q=>Math.hypot(q.x-candidate.x,q.y-candidate.y)<1.4)||people.some(q=>Math.hypot(q.x-candidate.x,q.y-candidate.y)<1.3||q.path.some(t=>Math.hypot(t.x-candidate.x,t.y-candidate.y)<.5))||workers.some(q=>q!==p&&Math.hypot(q.x-candidate.x,q.y-candidate.y)<1.3))continue;const route=path(p,candidate);if(route&&route.length<=7){target=candidate;p.path=route;break;}}p.idleWait25=6+idx*2;if(target){p.idleWalk25=true;p.targetId=null;p.state='둘러보는 중';p.lookTarget=null;}}
}




