function markValid26(base,m,rear=false){if(!BaseArt26[base]||!m||!C26.motifs.some(r=>r[0]===m.id)||!C26.material.some(r=>r[0]===m.material)||!C26.colors.some(r=>r[0]===m.color)||Object.keys(m).some(k=>!['id','x','y','scale','rotation','color','material'].includes(k))||!['x','y','scale','rotation'].every(k=>Number.isFinite(m[k]))||m.scale<.04||m.scale>1.8||m.rotation< -180||m.rotation>180||m.x< -1||m.x>2||m.y< -.5||m.y>2)return false;const a=BaseArt26[base].views[rear?1:0],g=modelGeometry26(base,rear),box=markBox26(base,m,rear),co=Math.cos(m.rotation*Math.PI/180),si=Math.sin(m.rotation*Math.PI/180),hw=box.w/2,hh=box.h/g.ratio/2;for(const[y,spans]of a.mask){const dy=(y/a.h-m.y)/g.ratio;for(let n=0;n<spans.length;n+=2){let lo=spans[n]/a.w-m.x,hi=(spans[n]+spans[n+1])/a.w-m.x;for(const[k,offset,limit]of[[co,si*dy,hw],[-si,co*dy,hh]]){if(Math.abs(k)<1e-9){if(Math.abs(offset)>limit){hi=lo-1;break;}}else{const p=(-limit-offset)/k,q=(limit-offset)/k;lo=Math.max(lo,Math.min(p,q));hi=Math.min(hi,Math.max(p,q));}}if(hi>=lo)return true;}}return false;}
