function selectBase26(base){if(base===workshopDraft?.base)return true;if(!customBases().includes(base))return false;if(!assetGate(designAssets26(base),()=>selectBase26(base),'악기의 기본 바디를 준비하고 있어요…'))return false;const old=workshopDraft.options.design26,d=defaults26(base,benchLevel());for(const k of ['bodyWood','neckWood','fretWood','bodyColor','neckColor','headColor','paint','color2','coat','metal','inlay','finish'])if(rows26(base,k).some(r=>r[0]===old[k]&&r[3]<=benchLevel()))d[k]=old[k];if(d.paint!=='gradient')d.coat='standard';workshopDraft={base,options:options26(d)};selectedMark26=-1;workshopAngle=0;renderWorkshop();return true;}
function setCustomDraftOption(key,value){if(!workshopDraft?.options?.design26)return before26SetCustomDraftOption(key,value);if(key==='base')return selectBase26(Number(value));const k=({color:'bodyColor',wood:'bodyWood',hardware:'metal',pickup:'pickupSpec'})[key]??key;return setDesign26(k,value==='chrome'?'silver':value==='ivory'?'white':value==='satin'?'matte':value);}
function setDesign26(key,value){if(!Fields26.includes(key)||!workshopDraft?.options?.design26)return false;const base=workshopDraft.base,d=JSON.parse(JSON.stringify(workshopDraft.options.design26));if(!rows26(base,key,d).some(r=>r[0]===value&&r[3]<=benchLevel()))return false;d[key]=value;if(key==='neckColor'){workshopAngle=180;selectedMark26=-1;}if(key==='pickupShape'&&!rows26(base,'pickupSpec',d).some(r=>r[0]===d.pickupSpec))d.pickupSpec='standard';if(key==='bodyWood'&&value!=='flame')d.woodGrade='standard';if(key==='inlay'&&value==='none')d.inlayMaterial='standard';if(key==='paint'&&value!=='gradient')d.coat='standard';if(key==='engraving'&&value!=='none'&&!d.front.length&&!d.back.length){toast('문양을 먼저 추가해주세요');return false;}if(!validateDesign26(base,d,benchLevel()))return false;workshopDraft.options=options26(d);renderWorkshop();return true;}
function activeSide26(){return Math.cos(workshopAngle*Math.PI/180)<0?'back':'front';}
function addMark26(id){if(!workshopDraft?.options?.design26)return false;const row=C26.motifs.find(r=>r[0]===id&&r[3]<=benchLevel()),d=JSON.parse(JSON.stringify(workshopDraft.options.design26)),side=activeSide26();if(!row||d[side].length>=3){toast('앞·뒷면에 각각 3개까지 놓을 수 있어요');return false;}let candidate=null;for(const scale of[.20,.15,.10,.08]){for(const y of[.86,.78,.92,.69,.60,...Array.from({length:19},(_,i)=>.50+i*.025)]){for(const x of[.22,.78,.34,.65,.50,.13,.87,...Array.from({length:33},(_,i)=>.10+i*.025)]){const m={id,x,y,scale,rotation:0,color:'white',material:'paint'};if(markValid26(workshopDraft.base,m,side==='back')){candidate=m;break;}}if(candidate)break;}if(candidate)break;}if(!candidate){toast('현재 면에 문양을 놓을 공간이 부족해요');return false;}d[side].push(candidate);workshopDraft.options=options26(d);selectedMark26=d[side].length-1;renderWorkshop();return true;}
function changeMark26(change,quiet=false){const side=activeSide26(),d=JSON.parse(JSON.stringify(workshopDraft.options.design26)),m=d[side][selectedMark26];if(!m)return false;Object.assign(m,change);for(const k of['x','y','scale','rotation'])m[k]=Math.round(m[k]*10000)/10000;if(!validateDesign26(workshopDraft.base,d,benchLevel())){if(!quiet)toast('문양 일부가 바디 안에 보이도록 배치해주세요');return false;}workshopDraft.options=options26(d);if(quiet){drawCustomModel();updateWorkshop26();}else renderWorkshop();return true;}
