  S.money -= S.dayRent + wage;
  S.expenses += S.dayRent + wage;
  S.opened = false;
  S.phase = 'settled';
  gainReputation(Config.reputation.closing);
  S.missionStats.bestDay = Math.max(S.missionStats.bestDay, S.sold);
